const CFG_KEYS = Object.keys(cfg);
function applyConfig(o) {
  if (o.removed) {
    C.shift();
    sel = 0;
  }
  if (o.computers !== undefined) makeComputers(+o.computers);
  if (o.sel !== undefined) sel = Math.max(0, Math.min(C.length - 1, +o.sel));
  if (o.state && C[sel]) C[sel].state = o.state;
  if (o.view) cur = o.view;
  for (const [k, v] of Object.entries(o)) {
    if (CFG_KEYS.includes(k)) cfg[k] = v;
    else if (k in ui) ui[k] = v;
  }
  if (o.form) {
    form = {
      address: o.form === "idle" ? "" : "100.101.102.120",
      key: o.form === "idle" && phone ? "" : "sunna-example-key",
      name: "",
      state: o.form,
      revealed: !!o.reveal,
      link: !!o.link,
    };
    if (cur === "edit") {
      form.name = current().name;
      form.address = current().address;
    }
  }
  if (o.reveal) ui.keyRevealed = true;
  if (o.modifier) ui.modifier = { Ctrl: o.modifier };
  if (o.testOpen) ui.test = true;
  if (o.toast) setTimeout(() => toast(o.toast, o.toastAction || ""), 0);
  if (o.focus) setTimeout(() => $(`[data-own="${o.focus}"]`)?.focus(), 0);
  if (o.pulse)
    setTimeout(() => {
      const p = $(".pointer");
      if (p) {
        const ring = document.createElement("i");
        ring.className = "tap-ring";
        ring.style.cssText = `left:${p.offsetLeft - 10}px;top:${p.offsetTop - 10}px`;
        p.parentElement.append(ring);
      }
    }, 0);
}
function initialize() {
  makeComputers(params.has("computers") ? +params.get("computers") : 5);
  try {
    sel = Math.min(C.length - 1, +(localStorage.getItem("sunna-proto-last") || 0));
  } catch {}
  sel = Math.max(0, sel);
  const entry = CASES.find((x) => x.id === params.get("case"));
  if (entry) applyConfig(entry.config);
  if (params.has("computers")) makeComputers(+params.get("computers"));
  const obj = {};
  for (const [k, v] of params) {
    if (k.startsWith("state.")) {
      const id = k.slice(6),
        c = C.find((c) => c.id === id) || C[+id];
      if (c) c.state = v;
      continue;
    }
    if (k === "sel" || k === "zoom" || k === "floatX") obj[k] = +v;
    else if (k === "still" || k === "computers") continue;
    else if (k === "test") continue;
    else if (
      v === "true" ||
      v === "false" ||
      [
        "stats",
        "keyboard",
        "menu",
        "sound",
        "capture",
        "clipboard",
        "reduced",
        "permissionShown",
        "context",
        "remove",
        "testOpen",
        "streamError",
      ].includes(k)
    )
      obj[k] = v === "true" || v === "1";
    else obj[k] = v;
  }
  applyConfig(obj);
  if (params.get("test") === "0") ui.test = false;
  if (!C.length && cur === "computer") cur = "add";
  if (params.has("fail") && !params.has("view")) cur = "computer";
  if (params.has("ended")) cur = "computer";
  if (params.has("notice") && !params.has("view")) cur = "session";
  if (params.get("view") === "add" && !params.has("form")) form.state = "idle";
  if (params.get("view") === "edit" && !params.has("form"))
    form = {
      address: current().address,
      key: current().key,
      name: current().name,
      state: current().state,
      revealed: false,
    };
  setLongNames(params.get("longNames") === "1");
  render();
  renderTest();
  if (params.has("scroll") || entry?.config.scroll) {
    const el = $(".settings-view,.session-controls,.wall,.find-view");
    if (el) el.scrollTop = +(params.get("scroll") || entry.config.scroll);
  }
  if (ui.test && entry?.id.startsWith("A15")) $(".notification-example")?.scrollIntoView({ block: "center" });
  if (ui.idle) $(".float-buttons")?.style.setProperty("opacity", ".55");
}
function setLongNames(on) {
  ui.longNames = on;
  C.forEach((c) => {
    if (c.id === "mac") c.name = on ? "Priya's MacBook Pro 16-inch" : "MacBook Air";
  });
}
function testSelect(id, items, value) {
  const options = items.map((x) => (Array.isArray(x) ? x : [x, x]));
  return `<details class="test-choice" id="${id}"><summary>${esc(options.find((x) => String(x[0]) === String(value))?.[1] || value)}</summary><div role="listbox">${options.map(([v, label]) => `<button type="button" data-test-value="${esc(v)}" aria-selected="${String(v) === String(value)}">${esc(label)}</button>`).join("")}</div></details>`;
}
function renderTest() {
  const root = $("#test-root");
  if (params.get("test") === "0") {
    root.innerHTML = "";
    return;
  }
  root.innerHTML = `<button class="test-tab" id="test-open" aria-label="Open prototype test controls">Test</button>${ui.test ? `<div class="test-backdrop" id="test-dismiss"></div><aside class="test-panel" aria-label="Prototype test controls"><header><h2>Prototype tests</h2><button id="test-close">Close</button></header><p class="note">Drawn screens. Changes stay in this tab. These controls are not part of Sunna.</p><label>Computers</label><div class="row">${[0, 1, 2, 5, 12].map((n) => `<button data-count="${n}">${n}</button>`).join("")}</div><label>Computer states</label>${C.map((c, i) => `<div class="machine-test"><span>${esc(c.name)}</span>${testSelect("state-" + i, STATES, c.state)}</div>`).join("")}<label for="test-view">View</label>${testSelect("test-view", ["computer", "overview", "add", "edit", "find", "qr", "settings", "connecting", "session", "menu", "licenses"], cur)}<label for="test-fail">Next connection</label>${testSelect("test-fail", [["success", "Succeed"], ...Object.entries(FAILS)], ui.nextFail)}<label for="test-notice">Session notice</label>${testSelect("test-notice", [["", "Choose a notice"], ...Object.entries(NOTICES)], "")}<label for="test-end">End session</label>${testSelect("test-end", [["", "Choose a reason"], ...Object.entries(FAILS)], "")}<label for="test-permission">Permission row</label>${testSelect("test-permission", ["allowed", "not-requested", "denied", "opened", "reset", "reset-failed"], ui.permission)}<label for="test-case">Every inventory state</label>${testSelect("test-case", [["", "Choose a state"], ...CASES.filter((c) => (phone ? c.id.startsWith("A") : !c.id.startsWith("A"))).map((c) => [c.id, `${c.id} · ${c.label}`])], params.get("case") || "")}<div class="setting-row"><span>Long names</span><button class="toggle" id="test-long-names" role="switch" aria-label="Long names" aria-checked="${!!ui.longNames}"></button></div><label>Motion</label><div class="row"><button id="test-reduce">Reduced motion: ${ui.reduced ? "on" : "off"}</button><button id="test-reset">Reset</button></div>${phone ? `<label>Foreground notification · drawn example</label>${testSelect("test-notification", ["starting", "connected", "background", "denied", "disconnected"], ui.notification)}<div class="notification-example"><small>Sunna · Sessions</small>${["denied", "disconnected"].includes(ui.notification) ? `<p>${ui.notification === "denied" ? "Notifications denied" : "Disconnected"}</p>` : `<b>Connected to ${esc(current().name)}</b><small>Tap to go back to it</small><button id="notification-return">Open</button><button id="notification-leave">Disconnect</button>`}</div>` : ""}<p class="note">URL: ${esc(location.pathname.split("/").at(-1))}?view=${cur}&sel=${sel}&test=0&still=1</p></aside>` : ""}`;
  $("#test-open").onclick = () => {
    ui.test = true;
    renderTest();
  };
  if (!ui.test) return;
  $$("[data-test-value]").forEach(
    (b) =>
      (b.onclick = () => {
        const list = b.closest("details");
        list.value = b.dataset.testValue;
        list.open = false;
        list.querySelector("summary").textContent = b.textContent;
        list.dispatchEvent(new Event("change", { bubbles: true }));
      }),
  );
  $("#test-long-names").onclick = () => {
    setLongNames(!ui.longNames);
    render();
    renderTest();
  };
  $("#test-close").onclick = $("#test-dismiss").onclick = () => {
    ui.test = false;
    renderTest();
  };
  $$("[data-count]").forEach(
    (b) =>
      (b.onclick = () => {
        makeComputers(+b.dataset.count);
        setLongNames(!!ui.longNames);
        cur = C.length ? "computer" : "add";
        form = { address: "", key: "", name: "", state: "idle" };
        render();
        renderTest();
      }),
  );
  C.forEach(
    (c, i) =>
      ($("#state-" + i).onchange = (e) => {
        c.state = e.target.value;
        sel = i;
        cur = "computer";
        ui.fail = ui.ended = "";
        render();
        renderTest();
      }),
  );
  $("#test-view").onchange = (e) => {
    cur = e.target.value;
    render();
  };
  $("#test-fail").onchange = (e) => (ui.nextFail = e.target.value);
  $("#test-notice").onchange = (e) => {
    if (!e.target.value) return;
    if (!["session", "menu"].includes(cur)) go("session");
    notice(e.target.value);
  };
  $("#test-end").onchange = (e) => {
    if (e.target.value) leave(e.target.value, true);
  };
  $("#test-permission").onchange = (e) => {
    ui.permission = e.target.value;
    ui.permissionShown = true;
    cur = "settings";
    render();
  };
  $("#test-case").onchange = (e) => {
    const c = CASES.find((x) => x.id === e.target.value);
    if (c) {
      applyConfig(c.config);
      render();
      renderTest();
      if (c.config.scroll) {
        const e = $(".settings-view,.session-controls,.wall,.find-view");
        if (e) e.scrollTop = c.config.scroll;
      }
      if (c.id.startsWith("A15")) $(".notification-example")?.scrollIntoView({ block: "center" });
    }
  };
  $("#test-reduce").onclick = () => {
    ui.reduced = !ui.reduced;
    render();
    renderTest();
  };
  $("#test-reset").onclick = () => {
    try {
      localStorage.removeItem("sunna-proto-last");
    } catch {}
    location.href = location.pathname;
  };
  if (phone) {
    $("#test-notification").onchange = (e) => {
      ui.notification = e.target.value;
      renderTest();
      $(".notification-example")?.scrollIntoView({ block: "center" });
    };
    $("#notification-return")?.addEventListener("click", () => {
      ui.test = false;
      go("session");
    });
    $("#notification-leave")?.addEventListener("click", () => {
      ui.notification = "disconnected";
      leave();
    });
  }
}
initialize();
